import librarySlugify from '@sindresorhus/slugify';
import { getUnicodeId } from './mdx/lib/unicode-id.js';
// decodes percent-encoded slugs and strips punctuation + emoji so the
// resulting ID matches what the client renders in the DOM
export const cleanHeadingId = (id) => {
    const decoded = decodeURIComponent(typeof id === 'string' ? id.replace(/%(?![0-9A-Fa-f]{2})/g, '%25') : id);
    return decoded
        .replace(/[?,;:!'"()[\]{}]/g, '')
        .replace(/\p{Emoji_Modifier}|\p{Emoji_Modifier_Base}|\p{Emoji_Presentation}|\p{Extended_Pictographic}|[\u200D\uFE0E\uFE0F]/gu, '');
};
// decodeURIComponent throws on malformed percent sequences (e.g. an author id
// of "100%1"); fall back to the raw id instead of crashing the render/compile
export const safeCleanHeadingId = (id) => {
    try {
        return cleanHeadingId(id);
    }
    catch (_a) {
        return id;
    }
};
const MAX_CACHED_SLUGS = 20000;
const slugCache = new Map();
// the library rebuilds ~2000 transliteration regexes per call
export function cachedSlugify(string, options) {
    const key = `${JSON.stringify(options !== null && options !== void 0 ? options : null)}\u0000${string}`;
    const cached = slugCache.get(key);
    if (cached !== undefined)
        return cached;
    const result = librarySlugify(string, options);
    if (slugCache.size >= MAX_CACHED_SLUGS)
        slugCache.clear();
    slugCache.set(key, result);
    return result;
}
// `slugifyWithCounter` from `@sindresorhus/slugify` 2.2.0, on top of cachedSlugify
export function cachedSlugifyWithCounter() {
    const occurrences = new Map();
    const countable = (string, options) => {
        string = cachedSlugify(string, options);
        if (!string) {
            return '';
        }
        const stringLower = string.toLowerCase();
        const numberless = occurrences.get(stringLower.replace(/(?:-\d+?)+?$/, '')) || 0;
        const counter = occurrences.get(stringLower);
        occurrences.set(stringLower, typeof counter === 'number' ? counter + 1 : 1);
        const newCounter = occurrences.get(stringLower) || 2;
        if (newCounter >= 2 || numberless > 2) {
            string = `${string}-${newCounter}`;
        }
        return string;
    };
    countable.reset = () => {
        occurrences.clear();
    };
    return countable;
}
export function slugify(string, slugify = cachedSlugifyWithCounter()) {
    const encodedString = getUnicodeId(string);
    // if encoded title is already percent-encoded, return it as is
    // slugify doesn't support percent-encoded characters, like Chinese, Korean, etc.
    if (/%[0-9A-F]{2}/.test(encodedString)) {
        return slugify(encodedString, {
            decamelize: false,
            preserveCharacters: ['%', '_'],
            lowercase: false,
        });
    }
    else {
        return slugify(encodedString, { decamelize: false, preserveCharacters: ['_'] });
    }
}
